// Библиотека упражнений на оборудовании зала (написана и проверена агентами-тренерами:
// реализуемость без силовой рамы, техника, безопасность, нагрузка на суставы).
// Поля как в exercises.js; load — нагрузка на суставы 0/1/2.
export const LIB = {
  legpress_wide:{n:'Жим ногами широко — ягодицы',g:'glutes',img:'legpress',t:'w',mech:'compound',lv:1,rr:'10–12',load:{knee:1,back:1,hip:2},setup:'Спинку отодвинь так, чтобы в нижней точке колени сгибались примерно до 90°, а таз не подкручивался. Стопы — в верхней части платформы, шире плеч, пятки целиком на платформе, носки развёрнуты наружу на 20–30°.',how:['Держись за рукояти у сиденья, таз и поясница прижаты к спинке','Толкай платформу пятками','Колени идут по линии носков — наружу, а не внутрь','Внизу почувствуй растяжение ягодиц, вверху не выпрямляй колени до замка'],bad:['Колени сводятся внутрь','Слишком глубоко — таз подкручивается, поясница отрывается от спинки','Толкаешь носками — нагрузка уходит в колени']},
  legpress_1leg:{n:'Жим одной ногой',g:'quads',img:'legpress',t:'w',x2:1,mech:'compound',lv:2,rr:'10–12',load:{knee:1,back:1,hip:1},setup:'Спинку отодвинь на 1–2 деления дальше, чем для жима двумя ногами, вес возьми вдвое меньше обычного. Рабочую стопу поставь в центр платформы на линии бедра, вторую — сбоку на платформу без давления: ею подстрахуешь себя, если не дожмёшь.',how:['Таз ровно прижат к сиденью, держись за рукояти','Толкай платформу пяткой рабочей ноги','Колено идёт по линии носка, не заваливается внутрь','Сделай все повторы, потом поменяй ногу'],bad:['Таз перекашивается и отрывается одной стороной','Колено заваливается внутрь','Весь подход помогаешь второй ногой']},
  calf_1leg:{n:'Икры одной ногой на жиме ногами',g:'calves',img:'legpress',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{ankle:1},setup:'Как в обычных икрах на жиме: нога почти прямая, но не в замке, подушечка стопы плотно на нижнем краю платформы, пятка висит. Вторую стопу поставь выше на платформу без давления — это страховка. Вес — на одну ногу.',how:['Опусти пятку вниз до растяжения икры','Поднимись на носок как можно выше','Пауза 1 секунда вверху, вниз медленно','Сделай все повторы и поменяй ногу'],bad:['Стопа на самом краешке — может соскользнуть; ставь плотно, обувь не скользкая','Сгибаешь и разгибаешь колено — толкаешь бедром, а не икрой','Пружинишь без паузы']},
  lat_1arm:{n:'Тяга верхнего блока одной рукой',g:'backv',img:'lat',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{shoulder:1,elbow:1},setup:'Сиденье подстрой так, чтобы валики плотно прижали бёдра. Тяни один рычаг, свободной рукой держись за валик. Вес — на одну руку.',how:['Рука прямая, плечо опусти вниз от уха','Тяни локоть вниз к своему боку','Корпус не поворачивай и не заваливай вбок','Вверх возвращай медленно, 2 секунды. Потом другая рука'],bad:['Скручиваешь корпус, чтобы дотянуть','Плечо поднимается к уху','Рывок вниз']},
  chest_1arm:{n:'Жим от груди одной рукой',g:'chest',img:'chest',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{shoulder:1,elbow:1},setup:'Сиденье как для обычного жима: рукояти на уровне середины груди. Нажми жёлтую педаль, возьми одну рукоять и плавно отпусти педаль; свободной рукой держись за край сиденья. Вес — на одну руку.',how:['Лопатки сведены, спина и плечи прижаты к спинке','Выжимай рукоять вперёд, локоть не выпрямляй до замка','Корпус не разворачивай вслед за рукой','Возвращай медленно до лёгкого растяжения груди. Потом другая рука'],bad:['Плечо уходит вперёд вслед за рукоятью','Скручиваешь корпус','Бросаешь рукоять в конце — отдавай вес через педаль']},
  shoulder_1arm:{n:'Жим плечами одной рукой',g:'press',img:'shoulder',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{shoulder:1,elbow:1,neck:1},setup:'Сиденье: рукояти на уровне плеч или чуть ниже. Педалью подай рукоять, возьми её одной рукой, второй держись за сиденье. Если плечо чувствительное — бери наклонную рукоять (ладонь смотрит внутрь), а не прямую.',how:['Спина и голова прижаты, пресс напряжён','Жми вверх, локоть чуть впереди корпуса','Корпус не наклоняй в сторону','Опускай медленно до уровня плеча. Потом другая рука'],bad:['Наклоняешься в сторону от рабочей руки','Прогиб в пояснице','Плечо поднимается к уху']},
  row_1arm:{n:'Горизонтальная тяга одной рукой',g:'backh',img:'row',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{shoulder:1,elbow:1},setup:'Сиденье и упор для груди — как для обычной тяги: в начале рука почти прямая, рукоять на уровне низа груди. Свободной рукой держись за упор или положи её на бедро. Вес — на одну руку.',how:['Грудь прижата к упору, корпус не поворачивай','Тяни локоть назад вдоль корпуса','В конце сведи лопатку к позвоночнику, пауза 1 секунда','Медленно вперёд до почти прямой руки. Потом другая рука'],bad:['Разворачиваешь корпус, чтобы дотянуть','Плечо поднимается к уху','Отрываешься от упора']},
  row_rear:{n:'Тяга на заднюю дельту',g:'rear',img:'row',t:'w',mech:'compound',lv:1,rr:'12–15',load:{shoulder:1},setup:'Тренажёр горизонтальной тяги. Сиденье опусти на 1–2 деления ниже обычного, чтобы рукояти оказались на уровне плеч, а упор остался на груди, а не у горла. Упор поставь так, чтобы в начале руки были прямые; вес заметно меньше, чем в обычной тяге.',how:['Грудь прижата к упору, плечи опущены, локти смотрят в стороны','Тяни локти назад и в стороны, держи их на уровне плеч','Остановись, когда локти на линии корпуса, пауза 1 секунда','Медленно верни руки вперёд'],bad:['Плечи поднимаются к ушам — работает трапеция','Локти опускаются к поясу — это уже обычная тяга','Большой вес и рывки']},
  row_scap:{n:'Сведение лопаток в тренажёре',g:'backh',img:'row',t:'w',mech:'isolation',lv:1,rr:'12–15',load:{},setup:'Тренажёр горизонтальной тяги. Сиденье и упор — как для обычной тяги, вес легче. Руки почти прямые всё упражнение, локти не в замке.',how:['Возьмись за рукояти, грудь прижата к упору','Не сгибая локтей, сведи лопатки назад — рукояти сдвинутся на несколько сантиметров','Пауза 2 секунды','Медленно отпусти лопатки вперёд'],bad:['Сгибаешь локти — получается обычная тяга','Плечи поднимаются к ушам','Слишком большой вес — лопатки не двигаются']},
  legcurl_1leg:{n:'Сгибание одной ноги сидя',g:'hams',img:'legcurl',t:'w',x2:1,mech:'isolation',lv:1,rr:'10–12',load:{knee:1},setup:'Настройка как для обычного сгибания: ось напротив колена, верхний валик плотно прижимает бёдра. Работает одна нога, вторую держи прямо чуть над нижним валиком и не опирайся на него. Вес — на одну ногу, начни с половины обычного.',how:['Сгибай ногу, подтягивая пятку под сиденье','Пауза 1 секунда внизу','Обратно медленно, 2–3 секунды','Сделай все повторы и поменяй ногу'],bad:['Помогаешь второй ногой или давишь ею на валик','Таз приподнимается с сиденья','Рывки']},
  legext_1leg:{n:'Разгибание одной ноги',g:'quads',img:'legext',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{knee:2},setup:'Спинку подвинь так, чтобы ось была напротив колена, валик — над лодыжкой; ограничителем выставь старт с коленом под прямым углом, не глубже. Работает одна нога, вторую согни и убери под сиденье. Вес — на одну ногу, начни с половины обычного.',how:['Держись за рукояти у сиденья, таз прижат','Разгибай ногу за 1–2 секунды почти до прямой','Пауза 1 секунда вверху, бедро напряжено','Опускай медленно, 2–3 секунды. Потом другая нога'],bad:['Любая боль в колене — сразу стоп','Рывок вверх и бросание вниз','Таз отрывается от сиденья']},
  legext_hold:{n:'Удержание на разгибании ног',g:'quads',img:'legext',t:'t',mech:'isolation',lv:1,rr:'30–45',load:{knee:1},setup:'Валик над лодыжками, ось напротив колена, ограничителем выставь старт с коленями под прямым углом. Вес подбери так, чтобы держать 30–45 секунд было тяжело для мышц, но без боли в колене.',how:['Держись за рукояти, таз прижат к сиденью','Разогни ноги примерно на треть пути — колени ещё заметно согнуты — и замри','Держи, дыши ровно, бёдра напряжены','Медленно опусти валик, отдохни 1–2 минуты'],bad:['Боль в колене — уменьши вес или прекрати','Задерживаешь дыхание','Валик ползёт вверх-вниз — держи одну точку']},
  smith_box_squat:{n:'Присед в Смите на скамью',g:'quads',img:'smith',t:'w',mech:'compound',lv:1,rr:'10–12',load:{knee:1,back:1,shoulder:1,neck:1,hip:1,ankle:1},setup:'Поставь скамью позади себя, спинку горизонтально: в нижней точке ты касаешься её ягодицами. Гриф повесь на крюки на уровне верха груди, нижние упоры выставь чуть ниже грифа в нижней точке. Коленям тяжело — положи на скамью сложенный коврик, амплитуда станет меньше.',how:['Встань под гриф, положи его на верх трапеций, стопы на ширине плеч и чуть впереди грифа.','Выпрямись, сними гриф с крюков поворотом кистей, напряги пресс.','Отводи таз назад и вниз, пока ягодицы мягко не коснутся скамьи.','Не садись полностью — сразу вставай, давя всей стопой в пол.','В конце подхода поверни гриф обратно на крюки.'],bad:['Плюхаешься на скамью и расслабляешь спину','Колени заваливаются внутрь','Отрываешь пятки от пола']},
  smith_squat:{n:'Присед в Смите',g:'quads',img:'smith',t:'w',mech:'compound',lv:2,rr:'8–10',load:{knee:2,back:1,shoulder:1,neck:1,hip:1,ankle:1},setup:'Гриф повесь на крюки на уровне верха груди, нижние упоры выставь чуть ниже грифа в твоей нижней точке. Стопы на ширине плеч, немного впереди грифа, носки слегка врозь.',how:['Положи гриф на верх трапеций, хват чуть шире плеч, выпрямись и сними гриф с крюков поворотом кистей.','Вдохни, напряги пресс и опускайся, сгибая колени и отводя таз назад.','Опускайся до параллели бедра с полом; глубже — только если поясница не скругляется и колени не болят.','Вставай, давя всей стопой в пол, на подъёме выдох. Колени смотрят туда же, куда носки.'],bad:['Стопы прямо под грифом — колени уходят далеко вперёд и перегружаются','Колени сводятся внутрь при подъёме','Поясница скругляется внизу']},
  smith_split_squat:{n:'Выпады на месте в Смите',g:'quads',img:'smith',t:'w',x2:1,mech:'compound',lv:1,rr:'8–10',load:{knee:2,back:1,shoulder:1,neck:1,hip:1,ankle:1},setup:'Гриф повесь на крюки чуть ниже плеч, нижние упоры выставь чуть ниже грифа в нижней точке. Под заднее колено положи сложенный коврик. Повторы — на каждую ногу.',how:['Положи гриф на верх трапеций и встань в длинную разножку: передняя стопа примерно на полшага впереди грифа, задняя нога — на полшага позади, на носке.','Выпрямись и сними гриф с крюков поворотом кистей, корпус ровный.','Опускайся строго вниз, пока заднее колено почти не коснётся коврика.','Поднимайся, давя всей стопой передней ноги. Закончи подход и смени ногу.'],bad:['Короткий шаг — пятка передней ноги отрывается, колено уезжает вперёд','Переднее колено заваливается внутрь','Толкаешься в основном задней ногой']},
  smith_bulgarian:{n:'Болгарский присед в Смите',g:'quads',img:'smith',t:'w',x2:1,mech:'compound',lv:2,rr:'8–10',load:{knee:2,back:1,shoulder:1,neck:1,hip:1,ankle:1},setup:'Скамью поставь торцом к грифу, в шаге позади него, спинку горизонтально. Гриф повесь на крюки чуть ниже плеч, нижние упоры — чуть ниже грифа в нижней точке. Повторы — на каждую ногу, первый раз делай с пустым грифом.',how:['Встань под гриф, положи его на верх трапеций, переднюю стопу поставь примерно на полшага впереди грифа.','Заднюю стопу положи подъёмом на скамью, выпрямись и сними гриф с крюков поворотом кистей.','Опускайся, пока бедро передней ноги не станет почти параллельно полу, корпус чуть наклонён вперёд.','Поднимайся, давя всей стопой передней ноги. Закончи подход и смени ногу.'],bad:['Передняя стопа слишком близко к скамье — пятка отрывается, колено уезжает вперёд','Отталкиваешься задней ногой вместо передней','Переднее колено заваливается внутрь']},
  smith_rdl:{n:'Румынская тяга в Смите',g:'hams',img:'smith',t:'w',mech:'compound',lv:2,rr:'8–10',load:{back:2,hip:1},setup:'Гриф повесь на крюки на уровне середины бедра — поднимать его с пола не придётся. Нижние упоры выставь чуть ниже твоей нижней точки, примерно на середине голени. Встань вплотную к грифу, стопы на ширине таза.',how:['Возьми гриф хватом чуть шире бёдер, выпрямись и сними его с крюков поворотом кистей.','Слегка согни колени и отводи таз назад — гриф скользит вниз по бёдрам.','Спина прямая, опускайся до сильного натяжения задней поверхности бедра — обычно чуть ниже колен.','Вернись вверх, толкая таз вперёд и сжимая ягодицы. В конце подхода повесь гриф на крюки.'],bad:['Скругляешь поясницу, чтобы опуститься ниже','Приседаешь вместо наклона — колени сильно сгибаются','Стоишь далеко — гриф отходит от ног']},
  smith_inverted_row:{n:'Австралийские подтягивания в Смите',g:'backh',img:'smith',t:'r',mech:'compound',lv:1,rr:'8–12',load:{shoulder:1,elbow:1},setup:'Гриф повесь на крюки на уровне пояса, нижние упоры выставь сразу под ним — на случай, если гриф соскочит. Легче — согни колени, тяжелее — повесь гриф на крюки ниже.',how:['Ляг под гриф так, чтобы он был над грудью, возьмись хватом чуть шире плеч, пятки на полу.','Напряги пресс и ягодицы: тело — ровная линия от плеч до пяток.','Тяни грудь к грифу, сводя лопатки. Гриф в руках не проворачивай — он может сойти с крюков.','Медленно опустись до прямых рук.'],bad:['Провисает таз','Тянешься к грифу подбородком, а не грудью','Плечи поднимаются к ушам']},
  smith_bent_row:{n:'Тяга в наклоне в Смите',g:'backh',img:'smith',t:'w',mech:'compound',lv:2,rr:'8–12',load:{back:2,shoulder:1,elbow:1,hip:1},setup:'Гриф повесь на крюки чуть выше колен — снимешь его сразу в наклоне, не поднимая с пола. Нижние упоры выставь на середине голени. Встань вплотную к грифу, стопы на ширине таза.',how:['Наклонись с прямой спиной примерно на 45°, колени слегка согнуты, возьми гриф хватом чуть шире плеч.','Сними гриф с крюков поворотом кистей, напряги пресс.','Тяни гриф к животу, локти веди назад вдоль корпуса, сводя лопатки.','Медленно опусти гриф до прямых рук, наклон корпуса не меняй.'],bad:['Округляешь поясницу','Раскачиваешься корпусом, помогая себе','Тянешь одними руками, не сводя лопатки']},
  smith_seated_press:{n:'Жим сидя в Смите',g:'press',img:'smith',t:'w',mech:'compound',lv:1,rr:'8–12',load:{back:1,shoulder:1,elbow:1,wrist:1},setup:'Спинку скамьи поставь почти вертикально, а скамью — так, чтобы гриф проходил перед лицом, не задевая нос. Гриф повесь на крюки на уровне лба сидя, нижние упоры выставь на уровне подбородка.',how:['Сядь, прижми спину и ягодицы к скамье, стопы твёрдо на полу.','Возьми гриф хватом чуть шире плеч и сними с крюков поворотом кистей.','Опускай гриф перед лицом до подбородка, локти чуть впереди грифа.','Выжми вверх до почти прямых рук, не прогибая поясницу.'],bad:['Опускаешь гриф за голову','Сильно прогибаешь поясницу и отрываешься от спинки','Разводишь локти строго в стороны']},
  smith_incline_press:{n:'Жим на наклонной в Смите',g:'chest',img:'smith',t:'w',mech:'compound',lv:1,rr:'8–12',load:{shoulder:1,elbow:1,wrist:1},setup:'Спинку скамьи поставь на 30°, а скамью — так, чтобы гриф опускался на верх груди под ключицы. Гриф повесь на крюки так, чтобы снимать его почти прямыми руками; нижние упоры выставь на уровне груди в нижней точке.',how:['Ляг, сведи и опусти лопатки, стопы на полу.','Возьми гриф хватом чуть шире плеч, сними поворотом кистей.','Опускай гриф на верх груди, локти под углом около 45° к корпусу.','Выжми вверх, не отрывая лопатки и таз от скамьи.'],bad:['Слишком крутой наклон — работают плечи, а не грудь','Отбиваешь гриф от груди','Отрываешь таз от скамьи']},
  smith_close_grip:{n:'Жим узким хватом в Смите',g:'triceps',img:'smith',t:'w',mech:'compound',lv:1,rr:'8–12',load:{shoulder:1,elbow:1,wrist:1},setup:'Скамья горизонтально, поставь её так, чтобы гриф опускался на низ груди. Гриф повесь на крюки так, чтобы снимать его почти прямыми руками; нижние упоры — на уровне груди в нижней точке.',how:['Ляг, сведи лопатки, возьми гриф хватом на ширине плеч.','Сними гриф поворотом кистей и опускай к низу груди, локти веди вдоль корпуса.','Выжми вверх за счёт трицепса до почти прямых рук.','Запястья держи ровно — гриф прямо над предплечьями.'],bad:['Слишком узкий хват — болят запястья','Локти разлетаются в стороны','Опускаешь гриф на верх груди или к шее']},
  smith_bar_pushup:{n:'Отжимания от грифа Смита',g:'chest',img:'smith',t:'r',mech:'compound',lv:1,rr:'10–15',load:{shoulder:1,elbow:1,wrist:1},setup:'Гриф повесь на крюки примерно на уровне пояса, нижние упоры выставь сразу под ним. Станет легко — вешай гриф на крюки ниже.',how:['Возьмись за гриф хватом чуть шире плеч и отойди ногами назад.','Тело — ровная линия, пресс и ягодицы напряжены.','Опускайся грудью к грифу, локти под углом около 45° к корпусу. Гриф в руках не проворачивай.','Отожмись до прямых рук, не прогибая поясницу.'],bad:['Провисает поясница','Локти разведены строго в стороны','Не доходишь грудью до грифа']},
  smith_seated_calf:{n:'Икры сидя в Смите',g:'calves',img:'smith',t:'w',mech:'isolation',lv:1,rr:'15–20',load:{knee:1,ankle:2},setup:'Поставь скамью внутри Смита и сядь на её край так, чтобы гриф был над бёдрами у колен; перед собой положи на пол блин для носков. Гриф повесь на крюки чуть выше бёдер, нижние упоры выставь чуть ниже грифа, когда пятки опущены. На бёдра положи сложенное полотенце.',how:['Поставь носки на край блина, гриф — на бёдра чуть выше колен.','Поднимись на носки — бёдра приподнимут гриф — и сними его с крюков поворотом кистей.','Опусти пятки как можно ниже, почувствуй растяжение икр.','Поднимись на носки максимально высоко и задержись на секунду.'],bad:['Короткая амплитуда — пятки не опускаются вниз','Пружинишь без паузы вверху и внизу','Гриф лежит прямо на коленных чашечках']},
  smith_kneeling_squat:{n:'Присед на коленях в Смите',g:'glutes',img:'smith',t:'w',mech:'isolation',lv:2,rr:'10–12',load:{knee:2,back:1,shoulder:1,neck:1,hip:1},setup:'Под колени положи сложенный коврик. Гриф повесь на крюки на уровне трапеций, когда стоишь на коленях; нижние упоры — чуть ниже грифа, когда сидишь на пятках. Вся опора идёт на колени — если они болят, выбери другое упражнение.',how:['Встань на колени под гриф, положи его на трапеции, выпрямись и сними с крюков поворотом кистей.','Отводи таз назад к пяткам, корпус наклоняется вперёд, спина прямая.','Выведи таз вперёд, сжимая ягодицы, до прямой линии от колен до плеч.','Вверху не прогибай поясницу — заканчивай движение ягодицами.'],bad:['Прогибаешь поясницу вверху вместо работы ягодиц','Стоишь коленями на голом полу','Гриф лежит на шее, а не на трапециях']},
  cable_low_fly:{n:'Сведение рук снизу вверх',g:'chest',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Кроссовер: оба блока в самый низ, D-рукоятки. Возьми рукояти, встань по центру и сделай шаг вперёд, ноги в разножку.',how:['Руки внизу по бокам, ладони смотрят вперёд, локти чуть согнуты','Своди руки по дуге вперёд-вверх до уровня подбородка','Вверху сожми грудь, пауза 1 секунда','Медленно опусти руки до лёгкого растяжения груди'],bad:['Сгибаешь локти и тянешь бицепсом','Плечи поднимаются к ушам','Прогибаешься в пояснице']},
  cable_high_fly:{n:'Сведение рук сверху вниз',g:'chest',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Кроссовер: оба блока в самый верх, D-рукоятки. Встань по центру, шаг вперёд, корпус чуть наклони вперёд.',how:['Руки разведены чуть выше плеч, локти слегка согнуты','Своди руки по дуге вниз-вперёд к низу живота','Внизу кисти почти касаются, пауза 1 секунда','Медленно разведи руки до растяжения груди'],bad:['Сгибаешь локти — получается жим вниз','Слишком далеко уводишь руки назад — тянет плечо','Раскачиваешься корпусом']},
  cable_press_1arm:{n:'Жим от груди одной рукой на блоке',g:'chest',img:'cable',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{shoulder:1},setup:'Кроссовер: блок на уровне груди, D-рукоять. Встань спиной к стойке, шаг вперёд. Ноги в разножку: жмёшь правой — впереди левая нога.',how:['Рукоять у груди, локоть под 45° к корпусу','Выжми руку вперёд, корпус не поворачивается','Не выпрямляй локоть до щелчка','Медленно верни до лёгкого растяжения груди. Потом другая рука'],bad:['Корпус разворачивается вслед за рукой','Плечо уходит вперёд и вверх','Прогиб в пояснице']},
  cable_scap_pullup:{n:'Подтягивания лопатками',g:'backv',img:'cable',t:'r',mech:'isolation',lv:1,rr:'8–10',load:{shoulder:1,wrist:1},setup:'Турник сверху кроссовера. Хват сверху чуть шире плеч, вис на прямых руках. Не достаёшь — встань на скамью; тяжело висеть — оставь носки на скамье.',how:['Руки прямые всё время','Опусти плечи вниз и чуть сведи лопатки — тело немного поднимется','Пауза 2 секунды','Плавно вернись в вис'],bad:['Сгибаешь руки — это уже подтягивание','Раскачиваешься','Резко падаешь в вис']},
  cable_reardelt_1arm:{n:'Задняя дельта одной рукой',g:'rear',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Кроссовер: блок на уровне плеч, D-рукоять. Встань лицом к стойке в шаге от неё. Рукоять бери противоположной рукой: левый блок — правой.',how:['Рука почти прямая, локоть чуть согнут','Отводи руку по дуге в сторону-назад до линии плеч','Пауза 1 секунда','Медленно верни руку перед грудью. Потом другая рука'],bad:['Разворачиваешь корпус вслед за рукой','Сгибаешь локоть — получается тяга','Большой вес — дёргаешь спиной']},
  cable_ext_rotation:{n:'Наружная ротация плеча',g:'rear',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'15–20',load:{shoulder:1},setup:'Кроссовер: блок на уровне локтя, D-рукоять, самый лёгкий вес. Встань боком к стойке, работает дальняя рука. Зажми между локтем и боком свёрнутое полотенце.',how:['Локоть согнут под 90° и прижат к боку, кисть прямая','Поворачивай предплечье наружу, от живота в сторону','Плечо не поднимается, локоть не отходит','Медленно верни к животу. Потом другая рука'],bad:['Локоть отходит от корпуса','Поворачиваешь корпус вместо плеча','Большой вес — здесь нужен самый лёгкий']},
  cable_lateral_1arm:{n:'Махи в сторону на нижнем блоке',g:'side',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Кроссовер: блок в самый низ, D-рукоять. Встань боком к стойке, рукоять в дальней руке, трос идёт перед телом. Ближней рукой держись за стойку.',how:['Локоть чуть согнут, корпус ровный','Поднимай руку в сторону до уровня плеча','Локоть ведёт движение, кисть не выше локтя','Медленно опускай, 2–3 секунды. Потом другая рука'],bad:['Раскачиваешь корпус, чтобы закинуть вес','Плечо поднимается к уху','Рывок от бедра']},
  cable_front_raise:{n:'Подъём перед собой на блоке',g:'press',img:'cable',t:'w',mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Кроссовер: блок в самый низ, канат. Встань спиной к стойке, трос проходит между ног. Пресс напряжён.',how:['Руки почти прямые, локти чуть согнуты','Поднимай руки вперёд до уровня плеч','Пауза 1 секунда','Медленно опускай к бёдрам'],bad:['Раскачиваешь корпус и прогибаешься назад','Поднимаешь руки выше головы','Плечи тянутся к ушам']},
  cable_rope_hammer:{n:'Молотки канатом на нижнем блоке',g:'biceps',img:'cable',t:'w',mech:'isolation',lv:1,rr:'10–12',load:{elbow:1},setup:'Кроссовер: блок в самый низ, канат. Встань лицом к стойке в полушаге от неё, ладони смотрят друг на друга.',how:['Локти прижаты к корпусу','Сгибай руки, концы каната идут к плечам','Вверху пауза 1 секунда','Медленно опускай до почти прямых рук'],bad:['Раскачиваешь корпус','Локти уходят вперёд','Кисти заворачиваются — держи их ровно']},
  cable_high_curl:{n:'Бицепс на верхнем блоке',g:'biceps',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1,elbow:1},setup:'Кроссовер: один блок на уровне плеча, D-рукоять, ладонь вверх. Встань боком к стойке и отойди так, чтобы прямая рука, вытянутая в сторону к блоку, держала трос в натяжении.',how:['Рука вытянута в сторону на уровне плеча, локоть неподвижен','Сгибай руку, подводя рукоять к уху','Пауза 1 секунда — сожми бицепс','Медленно разгибай руку до почти прямой. Потом другая рука'],bad:['Локоть опускается вниз','Наклоняешься корпусом к блоку','Плечо поднимается к уху']},
  cable_tri_kickback:{n:'Разгибание руки назад на блоке',g:'triceps',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{back:1,elbow:1},setup:'Кроссовер: блок в самый низ, D-рукоять. Встань лицом к стойке, наклони корпус примерно на 45° с ровной спиной, свободной рукой держись за стойку.',how:['Плечо прижато к корпусу и не двигается','Разгибай руку назад до прямой','Пауза 1 секунда — сожми трицепс','Медленно верни до угла 90° в локте. Потом другая рука'],bad:['Плечо гуляет вперёд-назад — работает уже спина','Круглая спина','Рывок вместо плавного движения']},
  cable_chinup:{n:'Подтягивания обратным хватом',g:'backv',img:'cable',t:'r',mech:'compound',lv:2,rr:'5–8',load:{shoulder:2,elbow:2,wrist:1},setup:'Турник сверху кроссовера, прямой участок перекладины. Хват снизу, ладони к себе, на ширине плеч. Не достаёшь — встань на скамью. Не получается ни разу — делай «Подтягивания / негативы».',how:['Начни из виса, плечи опусти вниз','Тянись грудью к перекладине, локти идут вниз к рёбрам','Подбородок выше перекладины','Опускайся медленно, 2–3 секунды, до почти прямых рук'],bad:['Рывки и раскачка ногами','Тянешься к перекладине подбородком, вытягивая шею','Падаешь вниз — это бьёт по локтям']},
  cable_bayesian_curl:{n:'Бицепс одной рукой спиной к блоку',g:'biceps',img:'cable',t:'w',x2:1,mech:'isolation',lv:2,rr:'10–12',load:{shoulder:1,elbow:1},setup:'Кроссовер: блок в самый низ, D-рукоять. Встань спиной к стойке, шагни вперёд в разножку, чтобы рука ушла чуть назад за корпус и трос натянулся.',how:['Плечо неподвижно, локоть чуть позади корпуса','Сгибай руку, подводя рукоять к плечу','Вверху сожми бицепс, пауза','Медленно разгибай до прямой руки. Потом другая рука'],bad:['Локоть уезжает вперёд — пропадает растяжение','Наклоняешься корпусом вперёд','Тяжёлый вес — тянет переднюю часть плеча']},
  cable_y_raise:{n:'Y-подъём на нижних блоках',g:'side',img:'cable',t:'w',x2:1,mech:'isolation',lv:2,rr:'12–15',load:{shoulder:2},setup:'Кроссовер: оба блока в самый низ, D-рукоятки, лёгкий вес. Возьми их крест-накрест: правый трос — левой рукой, левый — правой. Встань по центру на одной линии с блоками, чтобы тросы шли перед телом.',how:['Руки внизу перед бёдрами, локти чуть согнуты','Поднимай руки по диагонали вверх-в стороны, чуть впереди корпуса','Остановись, когда руки образуют букву Y — кисти чуть выше головы','Медленно опускай обратно крест-накрест'],bad:['Плечи поднимаются к ушам','Прогибаешься в пояснице','Вес тяжёлый — руки сгибаются, работает трапеция']},
  cable_pullthrough:{n:'Тяга каната между ног',g:'glutes',img:'cable',t:'w',mech:'compound',lv:1,rr:'12–15',load:{back:1,hip:1},setup:'Кроссовер: блок в самый низ, канат. Встань спиной к тренажёру над тросом, наклонись и возьми концы каната между ног. Выпрямись и отойди на 2 шага, стопы чуть шире плеч.',how:['Руки прямые и только держат канат — работают бёдра и ягодицы','Отводи таз назад, колени чуть согнуты, спина ровная — руки с канатом уходят назад между ног','Опускайся до растяжения задней поверхности бедра','Вставай, толкая таз вперёд и сжимая ягодицы, пауза 1 секунда'],bad:['Приседаешь вместо наклона — колени уходят вперёд','Круглая спина внизу','Вверху отклоняешься назад и прогибаешь поясницу']},
  cable_goblet_squat:{n:'Присед с канатом у груди',g:'quads',img:'cable',t:'w',mech:'compound',lv:1,rr:'10–12',load:{knee:2,back:1,hip:1,ankle:1},setup:'Кроссовер: блок в самый низ, канат. Встань лицом к тренажёру, возьми концы каната, подними их к груди и отойди на 1–2 шага, чтобы трос натянулся. Стопы чуть шире плеч, носки слегка врозь.',how:['Локти вниз, канат прижат к груди, пресс напряжён','Отводи таз назад и садись до удобной глубины — трос спереди помогает держать корпус ровно','Колени идут по линии носков, пятки прижаты к полу','Вставай, толкаясь пятками'],bad:['Колени заваливаются внутрь','Пятки отрываются от пола','Спина округляется внизу — садись не так глубоко']},
  cable_split_squat:{n:'Сплит-присед с канатом',g:'quads',img:'cable',t:'w',x2:1,mech:'compound',lv:1,rr:'8–10',load:{knee:2,hip:1,ankle:1},setup:'Кроссовер: блок в самый низ, канат. Встань лицом к тренажёру, концы каната у груди, отойди, чтобы трос натянулся, и встань в шаг: одна нога впереди, задняя на носке, стопы на ширине таза. Вес и повторы — на каждую ногу.',how:['Корпус прямой, вес на передней ноге','Опускайся строго вниз до удобной глубины — заднее колено идёт к полу, но не касается его','Переднее колено по линии носка, пятка прижата','Вставай, толкаясь передней пяткой. Сделай все повторы и смени ногу'],bad:['Стопы на одной линии — теряешь равновесие','Переднее колено заваливается внутрь','Толкаешься задней ногой — она только для равновесия']},
  cable_sl_rdl:{n:'Румынская тяга на одной ноге',g:'hams',img:'cable',t:'w',x2:1,mech:'compound',lv:2,rr:'8–10',load:{knee:1,back:1,hip:1,ankle:1},setup:'Кроссовер: блок в самый низ, D-рукоять. Встань лицом к тренажёру в 1,5–2 шагах от него. Рукоять держи в руке со стороны свободной ноги, то есть противоположной опорной. Вес и повторы — на каждую ногу.',how:['Стой на одной ноге, колено чуть согнуто и не меняет угол','Наклоняйся, отводя свободную ногу назад: корпус и нога — одна прямая линия','Рукоять опускается к середине голени, таз ровный и не разворачивается в сторону','Вставай, сжимая ягодицу опорной ноги. Теряешь равновесие — коснись пола носком и продолжай'],bad:['Таз раскрывается — свободная нога уходит в сторону','Круглая спина','Сгибаешь опорное колено — получается присед']},
  cable_leg_curl:{n:'Сгибание ноги стоя на блоке',g:'hams',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{knee:1},setup:'Кроссовер: блок в самый низ, манжета на щиколотку. Встань лицом к тренажёру, отступи на полшага-шаг, чтобы трос натянулся, и держись руками за стойку. Вес и повторы — на каждую ногу.',how:['Колени рядом, бедро рабочей ноги смотрит вниз и не двигается','Сгибай ногу, подтягивая пятку к ягодице','Пауза 1 секунда вверху','Медленно опускай, 2–3 секунды'],bad:['Выводишь колено вперёд — работает бедро, а не задняя поверхность','Прогибаешь поясницу','Рывки и раскачка']},
  cable_low_chop:{n:'Дровосек снизу вверх',g:'core',cr:'side',img:'cable',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{knee:1,back:2,shoulder:1,hip:1},setup:'Кроссовер: блок в самый низ, D-рукоять. Встань боком к тренажёру, ноги шире плеч, и отойди на шаг. Начни с лёгкого веса. Вес и повторы — на каждую сторону.',how:['Слегка присядь и возьми рукоять двумя руками у ближнего к блоку колена, спина ровная','Вставая, веди руки по диагонали вверх к точке над дальним плечом, руки почти прямые','Поворачивайся корпусом вместе с тазом — ближняя к блоку стопа разворачивается на носке','Медленно верни вниз. Сделай обе стороны'],bad:['Тянешь только руками','Стопы стоят на месте, а скручивается поясница','Рывок вверх с прогибом в пояснице']},
  cable_side_bend:{n:'Наклоны в сторону на блоке',g:'core',cr:'side',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{back:2},setup:'Кроссовер: блок в самый низ, D-рукоять в ближней к тренажёру руке. Встань боком и отойди на полшага, стопы на ширине таза. Начни с лёгкого веса. Вес и повторы — на каждую сторону.',how:['Стой прямо, свободная рука на поясе','Медленно наклонись к тренажёру — рука с рукоятью скользит вдоль бедра, амплитуда небольшая','Выпрямись до вертикали за счёт мышц противоположного бока','Наклон строго в сторону — без поворота и наклона вперёд'],bad:['Тяжёлый вес и глубокий наклон — грузит поясницу','Поворачиваешь корпус или наклоняешься вперёд','Рывки']},
  hanging_leg_raise:{n:'Подъём прямых ног в висе',g:'core',cr:'flex',img:'cable',t:'r',mech:'isolation',lv:2,rr:'6–10',load:{back:2,shoulder:1,elbow:1,wrist:1,hip:1},setup:'Турник сверху кроссовера: вис на прямых руках, плечи чуть опущены. Сначала освой подъём коленей в висе. Не достаёшь — поставь скамью сбоку, встань на неё, возьмись и сойди, чтобы ноги её не задевали.',how:['Не раскачивайся: стопы вместе, ноги почти прямые','Поднимай ноги до горизонтали, в конце подкручивая таз вверх','Пауза 1 секунда','Медленно опускай, 2–3 секунды'],bad:['Раскачка и махи','Таз не подкручивается — работают только сгибатели бедра','Бросаешь ноги вниз']},
  dbfrontraise:{n:'Подъём гантелей перед собой',g:'press',img:'db',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Стоя, стопы на ширине таза, гантели перед бёдрами, ладони смотрят на тебя или друг на друга. Вес лёгкий — примерно как для махов в стороны.',how:['Локти чуть согнуты, корпус неподвижен','Поднимай руки вперёд до уровня плеч','Пауза 1 секунда','Опускай медленно'],bad:['Раскачиваешься корпусом','Поднимаешь выше плеч','Плечи тянутся к ушам']},
  dbsplit:{n:'Сплит-присед с гантелями',g:'quads',img:'db',t:'w',x2:1,mech:'compound',lv:1,rr:'8–10',load:{knee:2,hip:1,ankle:1},setup:'Гантели в опущенных руках. Встань в широкий шаг: стопы на ширине таза, задняя нога на носке. Повторы — на каждую ногу.',how:['Корпус прямо, вес на передней ноге','Опускайся строго вниз, пока заднее колено почти не коснётся пола','Переднее колено идёт по линии носка','Вставай, толкаясь пяткой передней ноги'],bad:['Шаг слишком короткий — колено уходит далеко вперёд','Переднее колено заваливается внутрь','Бьёшь задним коленом об пол']},
  dbrevlunge:{n:'Выпады назад с гантелями',g:'glutes',img:'db',t:'w',x2:1,mech:'compound',lv:1,rr:'8–10',load:{knee:2,hip:1,ankle:1},setup:'Гантели в опущенных руках, стопы на ширине таза. Повторы — на каждую ногу: все на одну, потом на другую, или поочерёдно.',how:['Шагни назад и опустись, пока заднее колено почти не коснётся пола','Голень передней ноги почти вертикальна, корпус чуть наклонён вперёд','Колено передней ноги идёт по линии носка','Вернись в стойку, толкаясь пяткой передней ноги'],bad:['Ставишь стопы на одну линию — теряешь равновесие','Переднее колено заваливается внутрь','Отталкиваешься задней ногой вместо передней']},
  dbsumo:{n:'Сумо-присед с гантелью',g:'quads',img:'db',t:'w',mech:'compound',lv:1,rr:'10–12',load:{knee:2,back:1,hip:1},setup:'Стопы шире плеч, носки развёрнуты наружу на 30–45°. Одну гантель держи вертикально двумя руками под верхний блин, она висит между ног.',how:['Спина прямая, грудь вперёд','Опускайся, разводя колени по линии носков','Садись до параллели бёдер с полом или чуть выше','Вставай, толкаясь всей стопой и сжимая ягодицы'],bad:['Колени сводятся внутрь','Круглая спина внизу','Пятки отрываются от пола']},
  dbcalfone:{n:'Икры на одной ноге с гантелью',g:'calves',img:'db',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{ankle:2},setup:'Положи на пол блин от штанги и встань на его край подушечкой стопы, пятка свисает. Гантель — в руке со стороны рабочей ноги, другой рукой держись за стойку Смита или стойку с гантелями. Повторы — на каждую ногу.',how:['Нога почти прямая, колено не сгибай','Опусти пятку вниз до растяжения икры','Поднимись на носок как можно выше','Пауза 1 секунда вверху, опускайся медленно'],bad:['Пружинишь без паузы','Сгибаешь колено и помогаешь им','Подтягиваешься рукой за стойку']},
  farmer:{n:'Прогулка фермера',g:'core',cr:'stab',img:'db',t:'t',mech:'isolation',lv:1,rr:'30–40',load:{back:1,elbow:1,wrist:1,neck:1},setup:'По гантели в каждую руку — такие, чтобы ровно продержать 30–40 секунд. Сними их со стойки с прямой спиной. Иди по свободной части зала, а если места нет — стой на месте и держи.',how:['Встань ровно, плечи опусти вниз и чуть назад','Пресс напряжён, гантели не бьют по ногам','Иди короткими ровными шагами, дыши ровно','В конце верни гантели на стойку, не сгибая спину'],bad:['Сутулишься, плечи падают вперёд','Корпус раскачивается из стороны в сторону','Бросаешь гантели на пол']},
  dblatlunge:{n:'Боковые выпады с гантелью',g:'quads',img:'db',t:'w',x2:1,mech:'compound',lv:2,rr:'8–10',load:{knee:2,back:1,hip:2,ankle:1},setup:'Стопы вместе, одну гантель держи вертикально у груди двумя руками. Повторы — на каждую сторону.',how:['Сделай широкий шаг в сторону','Отведи таз назад и сядь на шагнувшую ногу, вторая остаётся прямой','Колено согнутой ноги идёт по линии носка, пятка на полу','Оттолкнись этой ногой и вернись в исходное положение'],bad:['Колено уходит внутрь или далеко за носок','Пятка рабочей ноги отрывается от пола','Круглая спина']},
  bench_reverse_hyper:{n:'Обратная гиперэкстензия на скамье',g:'glutes',img:'bench',t:'r',mech:'isolation',lv:1,rr:'12–15',load:{back:1,hip:1},setup:'Скамья горизонтально. Ляг на неё животом так, чтобы край скамьи был под тазовыми костями, а ноги свисали и носками касались пола. Руками крепко держись за скамью.',how:['Ноги почти прямые, пресс слегка напряжён.','Подними ноги до линии корпуса, сжимая ягодицы.','Задержись на секунду вверху.','Медленно опусти ноги до касания пола носками.'],bad:['Поднимаешь ноги выше корпуса и прогибаешь поясницу','Делаешь рывком, за счёт инерции','Таз лежит далеко от края — амплитуда пропадает']},
  dbchestrow:{n:'Тяга гантелей лёжа на наклонной',g:'backh',img:'bench',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{elbow:1},setup:'Спинка скамьи под 30–45°. Ляг грудью на спинку, подбородок над верхним краем, носки упираются в пол. Гантели висят на прямых руках, ладони смотрят друг на друга.',how:['Опусти плечи вниз, от ушей','Тяни гантели к поясу, локти идут назад вдоль корпуса','Вверху сведи лопатки на 1 секунду','Опускай медленно до прямых рук'],bad:['Отрываешь грудь от скамьи и помогаешь корпусом','Тянешь к груди, а не к поясу','Задираешь голову — смотри вниз']},
  dbreardelt:{n:'Разводка на заднюю дельту лёжа',g:'rear',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Спинка скамьи под 30°. Ляг грудью на спинку, носки упираются в пол. Лёгкие гантели (2–6 кг) висят вниз, ладони друг к другу.',how:['Локти чуть согнуты и не меняют угол','Разводи руки в стороны дугой до линии плеч','Пауза 1 секунда вверху','Опускай медленно, за 2 секунды'],bad:['Тяжёлые гантели и рывки','Сгибаешь локти — получается тяга, а не разводка','Плечи поднимаются к ушам']},
  dbyraise:{n:'Подъём рук буквой Y лёжа',g:'rear',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'10–12',load:{shoulder:1,neck:1},setup:'Спинка скамьи под 30–45°. Ляг грудью на спинку. Возьми самые лёгкие гантели, большие пальцы смотрят вверх; если тяжело даже с ними — делай без веса.',how:['Опусти плечи вниз, от ушей','Поднимай прямые руки вперёд-вверх и чуть в стороны — буквой Y, до линии корпуса','Задержись вверху на 1 секунду','Медленно опусти'],bad:['Слишком тяжело — вместо спины работает шея','Пожимаешь плечами к ушам','Отрываешь грудь от скамьи']},
  dbfly:{n:'Разводка гантелей лёжа',g:'chest',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:2,elbow:1},setup:'Скамья горизонтально или под 15–30°. Сядь с гантелями на бёдрах, ляг и подними их над грудью, ладони друг к другу. Вес в 2–3 раза легче, чем для жима.',how:['Локти чуть согнуты и не меняют угол','Разводи руки дугой в стороны до лёгкого растяжения груди','Локти не опускай ниже уровня скамьи','Своди руки той же дугой, будто обнимаешь бочку'],bad:['Слишком глубоко — перегружаешь плечо','Сгибаешь локти и превращаешь в жим','Берёшь тяжёлый вес']},
  dbinclinecurl:{n:'Бицепс сидя на наклонной',g:'biceps',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'10–12',load:{shoulder:1,elbow:1},setup:'Спинка скамьи под 45–60°. Сядь, прижми спину и голову, гантели висят на прямых руках, ладони вперёд. Вес легче, чем в обычном подъёме.',how:['Локти смотрят в пол и не уходят вперёд','Сгибай руки, поднимая гантели к плечам','Пауза 1 секунда','Опускай медленно до почти прямых рук'],bad:['Отрываешь плечи и голову от спинки','Локти уезжают вперёд','Бросаешь вес вниз — удар по локтю']},
  dbconccurl:{n:'Концентрированный подъём на бицепс',g:'biceps',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'10–12',load:{elbow:1},setup:'Сядь на край горизонтальной скамьи, ноги широко. Локоть рабочей руки упри во внутреннюю сторону бедра, гантель висит вниз. Повторы — на каждую руку.',how:['Корпус чуть наклонён вперёд, спина прямая','Сгибай руку, поднимая гантель к плечу','Вверху сожми бицепс на 1 секунду','Медленно опусти до почти прямой руки'],bad:['Откидываешься назад и помогаешь корпусом','Локоть соскальзывает с бедра','Не опускаешь руку до конца']},
  dbohext:{n:'Французский жим гантели сидя',g:'triceps',img:'bench',t:'w',mech:'isolation',lv:1,rr:'10–12',load:{back:1,shoulder:1,elbow:1},setup:'Скамья горизонтально: высокая спинка мешает опускать гантель за голову. Сядь на край, стопы на полу, спина прямая. Поставь гантель вертикально на бедро, обхвати ладонями верхний блин и подними над головой.',how:['Локти смотрят вперёд-вверх и держатся близко к голове','Опускай гантель за голову, сгибая только локти','Опускай до угла в локтях около 90° или чуть ниже','Разгибай руки вверх, плечи неподвижны'],bad:['Локти разъезжаются в стороны','Прогиб в пояснице — держи пресс напряжённым','Слишком тяжело — опасно для локтей и головы']},
  dbskull:{n:'Французский жим с гантелями лёжа',g:'triceps',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'10–12',load:{elbow:1},setup:'Скамья горизонтально. Сядь с гантелями на бёдрах, ляг и подними их над плечами на прямых руках, ладони друг к другу — так мягче для локтей и запястий.',how:['Плечи неподвижны, руки чуть наклонены к голове','Сгибай локти, опуская гантели по бокам от головы','Локти смотрят вверх и не расходятся','Разгибай руки, напрягая трицепс'],bad:['Локти разъезжаются в стороны','Двигаешь плечами — получается пуловер','Бросаешь гантели вниз']},
  dbtrikick:{n:'Разгибание руки в наклоне',g:'triceps',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{elbow:1,wrist:1},setup:'Скамья горизонтально. Колено и ладонь одной стороны на скамье, спина параллельна полу — как в тяге гантели. Лёгкая гантель в свободной руке. Повторы — на каждую руку.',how:['Подними локоть: плечо вдоль корпуса, параллельно полу','Разгибай руку назад до прямой линии','Вверху задержись на 1 секунду','Сгибай только локоть, плечо неподвижно'],bad:['Локоть опускается и болтается','Машешь гантелью по инерции','Скручиваешь корпус']},
  dbarnold:{n:'Жим Арнольда сидя',g:'press',img:'bench',t:'w',x2:1,mech:'compound',lv:2,rr:'10–12',load:{back:1,shoulder:2,elbow:1},setup:'Спинка почти вертикально, на одно деление ниже максимума. Закинь гантели к плечам: ладони смотрят на тебя, локти впереди.',how:['Спина прижата к спинке, пресс напряжён','Жми вверх и по пути разворачивай ладони вперёд','Вверху гантели над плечами, локти не выпрямляй до щелчка','Опускай тем же путём, разворачивая ладони к себе'],bad:['Прогиб в пояснице','Разворот рывком из-за тяжёлого веса','Гантели уходят вперёд, а не вверх над плечами']},
  dbpullover:{n:'Пуловер с гантелью лёжа',g:'backv',img:'bench',t:'w',mech:'isolation',lv:2,rr:'10–12',load:{shoulder:2,elbow:1},setup:'Скамья горизонтально, ляг вдоль неё, голова у самого края. Сядь с гантелью на бедре, ляг, прижав её к груди, и выжми над грудью, держа двумя ладонями под верхний блин. Держи крепко — гантель над лицом.',how:['Рёбра опущены, поясница прижата к скамье','Локти чуть согнуты и не меняют угол','Медленно опускай гантель дугой за голову, пока руки не дойдут до уровня ушей','Верни гантель над грудь той же дугой, напрягая широчайшие'],bad:['Опускаешь слишком глубоко — больно в плече','Сгибаешь и разгибаешь локти — работает трицепс','Прогибаешь поясницу']},
  dbbulgarian:{n:'Болгарский сплит-присед',g:'quads',img:'bench',t:'w',x2:1,mech:'compound',lv:2,rr:'8–10',load:{knee:2,hip:1,ankle:1},setup:'Скамья горизонтально позади тебя. Положи заднюю стопу шнурками на край сиденья, передняя стопа — в большом шаге впереди. Начни без гантелей, потом бери их в опущенные руки.',how:['Опускайся, пока бедро передней ноги не станет почти параллельно полу','Вес на передней ноге, задняя — только для равновесия','Переднее колено идёт по линии носка','Вставай, толкаясь пяткой передней ноги'],bad:['Стопа слишком близко к скамье — колено уходит далеко вперёд','Колено заваливается внутрь','Толкаешься задней ногой']},
  onelegbridge:{n:'Ягодичный мост на одной ноге',g:'glutes',img:'bench',t:'r',mech:'compound',lv:2,rr:'10–12',load:{knee:1,back:1,hip:1},setup:'Скамья горизонтально, длинной стороной к тебе — проверь, что она не качается и не уезжает. Нижний край лопаток — на край скамьи, одна стопа на полу ближе к ягодицам, вторая нога поднята. Повторы — на каждую ногу.',how:['Подбородок к груди, рёбра опущены','Толкайся пяткой и поднимай таз до прямой линии плечи — колено','Вверху сожми ягодицу на 1 секунду, таз ровный','Медленно опусти таз почти до пола'],bad:['Прогиб в пояснице вверху','Таз заваливается в сторону поднятой ноги','Толкаешься носком вместо пятки']},
  incline_pushup:{n:'Отжимания от скамьи',g:'chest',img:'bench',t:'r',mech:'compound',lv:1,rr:'10–15',load:{shoulder:1,elbow:1,wrist:1},setup:'Скамья горизонтально. Встань сбоку от неё, упрись ладонями в край сиденья чуть шире плеч и отставь ноги назад. Перед подходом проверь, что скамья стоит устойчиво и не едет.',how:['Тело от пяток до головы — прямая линия','Опускайся грудью к краю скамьи, локти под 45° к корпусу','Коснись скамьи грудью или почти','Выжми себя вверх'],bad:['Провисает поясница или задран таз','Локти разведены в стороны','Скамья ползёт — остановись и поставь её устойчиво']},
  bench_ham_bridge:{n:'Мост с ногами на скамье',g:'hams',img:'bench',t:'r',mech:'compound',lv:1,rr:'10–12',load:{knee:1,back:1,hip:1},setup:'Скамья горизонтально. Ляг на коврик на спину перед скамьёй, пятки положи на край сиденья, колени чуть согнуты. Руки на полу вдоль тела. Скамья не должна ехать — если сдвигается, подопри её к стене.',how:['Дави пятками в скамью','Подними таз до прямой линии плечи — таз — колени','Пауза 1–2 секунды','Медленно опусти таз. Стало легко — делай на одной ноге'],bad:['Прогиб в пояснице наверху','Сильно согнутые колени — работают ягодицы вместо задней поверхности бедра','Рывки и броски таза вниз']},
  copenhagen_plank:{n:'Копенгагенская планка',g:'core',cr:'side',img:'bench',t:'t',mech:'isolation',lv:2,rr:'15–20',load:{knee:1,shoulder:1,hip:2},setup:'Скамья горизонтально. Ляг на бок у скамьи, она — поперёк тела, опора на локоть под плечом. Верхнюю ногу согни под 90° и положи на сиденье: колено и голень лежат внутренней стороной. Начни с 10 секунд. Время — на каждую сторону.',how:['Подними таз: тело от головы до колена — прямая линия','Нижнюю ногу оторви от пола и держи под скамьёй. Тяжело — касайся пола носком','Держи, дыши ровно','Повтори на другую сторону'],bad:['Таз провисает к полу','Корпус заваливается вперёд или назад','Боль в паху или во внутренней части колена — сразу стоп']},
  ytw_raise:{n:'Y-T-W лёжа на наклонной скамье',g:'rear',img:'bench',t:'r',mech:'isolation',lv:1,rr:'6–8',load:{shoulder:1,neck:1},setup:'Спинка скамьи под 30–45°. Ляг на неё грудью, стопы на полу, руки свисают вниз. Голова над краем спинки, взгляд в пол. Делай без веса — этого достаточно.',how:['Y: подними прямые руки вперёд-вверх буквой Y, большие пальцы вверх','T: разведи прямые руки в стороны до уровня плеч','W: согни локти и потяни их назад-вниз, сводя лопатки','В каждом положении пауза 1 секунда. Один повтор — Y, T и W подряд'],bad:['Плечи поднимаются к ушам','Грудь отрывается от скамьи, поясница прогибается','Задираешь голову']},
  deadlift:{n:'Становая тяга',g:'hams',img:'barbell',t:'w',mech:'compound',lv:2,rr:'5–8',load:{knee:1,back:2,wrist:1,hip:2},setup:'Прямой гриф на полу: надень самые большие по диаметру блины и закрепи замками. Гриф должен лежать примерно на уровне середины голени. Если блины маленькие, поставь каждый на плоский блин-подставку.',how:['Встань: стопы на ширине таза, гриф над серединой стопы, в паре сантиметров от голеней.','Наклонись, возьмись хватом сверху чуть шире ног, затем согни колени, пока голени не коснутся грифа.','Грудь вперёд, спина ровная, плечи чуть впереди грифа. Вдохни животом, напряги пресс и широчайшие, руки прямые.','Толкай пол ногами и веди гриф вплотную по ногам. Наверху выпрямись полностью, без отклонения назад.','Опускай тем же путём: таз назад, после колен сгибай ноги. Ставь гриф на пол под контролем и заново собирай позицию.'],bad:['Круглая спина при отрыве от пола','Гриф уходит вперёд от ног','Таз взлетает раньше плеч — тянешь спиной']},
  bbrollout:{n:'Раскатка со штангой',g:'core',cr:'stab',img:'barbell',t:'r',mech:'compound',lv:2,rr:'6–10',load:{knee:1,back:2,shoulder:2,wrist:1},setup:'Надень на прямой гриф два одинаковых круглых блина по 10–15 кг и закрепи замками. Сложи коврик вдвое и встань на него коленями сразу за грифом.',how:['Возьмись за гриф хватом сверху на ширине плеч, плечи над грифом, руки прямые.','Подкрути таз под себя, напряги пресс и ягодицы, чтобы поясница не прогибалась.','Медленно кати гриф вперёд на прямых руках. Иди только до точки, где поясница ещё ровная; начни с 30–50 см.','Вернись назад силой пресса, подтягивая гриф прямыми руками, а не отводя таз.'],bad:['Провисание поясницы','Сразу слишком длинная амплитуда','Возврат за счёт таза и рук']},
  platelunge:{n:'Обратные выпады с блином',g:'quads',img:'barbell',t:'w',x2:1,mech:'compound',lv:1,rr:'8–10',load:{knee:2,hip:1,ankle:1},setup:'Возьми блин 5–15 кг обеими руками и прижми к груди. Нужен свободный участок пола около двух метров.',how:['Встань прямо, стопы на ширине таза, блин у груди.','Сделай широкий шаг назад и опустись, пока заднее колено почти не коснётся пола.','Вес на всей стопе передней ноги, колено идёт по линии носка, корпус ровный.','Оттолкнись передней ногой и вернись в стойку. Сделай все повторы на одну ногу, затем на другую.'],bad:['Переднее колено заваливается внутрь','Короткий шаг: передняя пятка отрывается','Удар задним коленом об пол']},
  kickstandrdl:{n:'Румынская тяга с опорой на носок',g:'hams',img:'barbell',t:'w',x2:1,mech:'compound',lv:2,rr:'8–10',load:{back:1,hip:1},setup:'Прямой гриф с весом заметно легче, чем в обычной румынской тяге. Подними его с пола, как в становой, и встань прямо.',how:['Отставь одну ногу назад, чтобы её носок был примерно на уровне пятки передней, и встань на этот носок. Задняя нога только для равновесия, вес на передней.','Переднее колено слегка согнуто. Отводи таз назад, гриф скользит по бедру.','Опускайся до натяжения под ягодицей и в задней поверхности бедра. Спина ровная, таз не разворачивается.','Вернись вверх, толкая пол пяткой передней ноги. Сделай все повторы и смени ногу.'],bad:['Перенос веса на заднюю ногу','Разворот таза в сторону','Круглая спина внизу']},
  ezrevcurl:{n:'Подъём EZ-грифа обратным хватом',g:'biceps',img:'ezbar',t:'w',mech:'isolation',lv:1,rr:'12–15',load:{elbow:2,wrist:2},setup:'EZ-гриф с лёгкими блинами, примерно вдвое легче, чем в обычном подъёме на бицепс. Хват сверху на внешних изгибах грифа, примерно на ширине плеч.',how:['Встань прямо, стопы на ширине таза, гриф у бёдер хватом сверху.','Прижми локти к бокам, запястья держи в одну линию с предплечьем.','Сгибай руки и поднимай гриф к груди, локти остаются на месте.','Опускай медленно, 2–3 секунды, до почти прямых рук.'],bad:['Запястья прогибаются вниз','Раскачка корпусом','Локти уезжают вперёд и вверх']},
  ezupright:{n:'Протяжка EZ-грифа широким хватом',g:'side',img:'ezbar',t:'w',mech:'compound',lv:1,rr:'10–12',load:{shoulder:2,wrist:1,neck:1},setup:'EZ-гриф с лёгким весом. Хват сверху на внешних изгибах или чуть шире, но не уже плеч. Если в плече колет или щёлкает, замени на махи гантелями в стороны.',how:['Встань прямо, гриф у бёдер, пресс напряжён, плечи опущены.','Тяни гриф вверх вдоль тела, ведя движение локтями в стороны.','Остановись, когда локти дошли до уровня плеч: гриф примерно у низа груди.','Опускай медленно, не роняя гриф.'],bad:['Тянуть к подбородку узким хватом','Поднимать локти выше плеч','Подтягивать плечи к ушам и раскачиваться']},
  ezfloorpress:{n:'Узкий жим EZ-грифа лёжа на полу',g:'triceps',img:'ezbar',t:'w',mech:'compound',lv:2,rr:'8–12',load:{shoulder:1,elbow:1,wrist:1},setup:'Расстели коврик. EZ-гриф с умеренным весом, хват сверху на внешних изгибах, примерно на ширине плеч. Страховщика нет, поэтому не жми до отказа: оставляй 1–2 повтора в запасе.',how:['Сядь на коврик, гриф на бёдрах. Прижми его к животу согнутыми руками и медленно ляг на спину: колени согнуты, стопы на полу.','Подтяни гриф к низу груди и выжми вверх до прямых рук.','Опускай к низу груди, локти идут вдоль тела, примерно под 30–45° к корпусу.','Коснись пола трицепсами, задержись на секунду, не расслабляясь, и выжимай.','После подхода опусти гриф на живот, перекати на бёдра и сядь.'],bad:['Отбивать локти от пола','Разводить локти в стороны','Запястья заваливаются назад: держи их над локтями']},
  ezinclinerow:{n:'Тяга EZ лёжа на наклонной',g:'rear',img:'ezbar',t:'w',mech:'compound',lv:1,rr:'12–15',load:{shoulder:1},setup:'Поставь спинку скамьи под 30°, EZ-гриф с лёгким весом положи на пол прямо под её верхним краем. Ляг грудью на спинку (верх груди у края, стопы в пол) и возьми гриф хватом сверху чуть шире плеч. Если не дотягиваешься, опусти спинку ниже.',how:['Руки прямые, гриф висит под плечами, подбородок слегка поджат.','Тяни гриф вверх к спинке, разводя локти в стороны, примерно под 70° к корпусу.','Наверху сведи лопатки и задержись на секунду.','Опускай медленно до прямых рук, грудь от спинки не отрывай. После подхода положи гриф на пол и только потом вставай.'],bad:['Отрывать грудь и раскачиваться','Прижимать локти к телу: тогда работает уже широчайшая','Задирать голову']},
  ezspidercurl:{n:'Паучьи сгибания с EZ-грифом',g:'biceps',img:'ezbar',t:'w',mech:'isolation',lv:1,rr:'10–12',load:{elbow:1,wrist:1},setup:'Поставь спинку скамьи под 30–45°, EZ-гриф с лёгким весом положи на пол прямо под её верхним краем. Ляг грудью на спинку так, чтобы руки свешивались вертикально вниз через край, и возьми гриф хватом снизу на изгибах. Если не дотягиваешься, опусти спинку ниже.',how:['Руки прямые и висят строго вниз, плечи неподвижны.','Сгибай руки, поднимая гриф к плечам. Локти остаются на месте.','Наверху сожми бицепс на секунду.','Опускай медленно, 2–3 секунды, до почти прямых рук. После подхода положи гриф на пол и вставай.'],bad:['Локти уходят назад к корпусу','Отрывать грудь от спинки и дёргать','Бросать гриф вниз и разгибать руки до щелчка']},
  situp:{n:'Подъём корпуса',g:'core',cr:'flex',img:'abbench',t:'r',mech:'isolation',lv:2,rr:'10–15',load:{back:2,neck:1,hip:1},setup:'Скамья для пресса: ноги под валики, ляг спиной на подушку, руки скрести на груди. Болит поясница — выбери обычные скручивания.',how:['Начни со скручивания: подбородок к груди, первыми отрываются лопатки','Поднимайся дальше, пока корпус не станет почти вертикальным','Опускайся медленно, 2–3 секунды: сначала поясница, потом лопатки','Внизу не расслабляйся — сразу следующий повтор'],bad:['Рывок с размаху — работают ноги и поясница','Руки за головой тянут шею','Падаешь спиной на подушку']},
  oblique_crunch:{n:'Косые скручивания',g:'core',cr:'side',img:'abbench',t:'r',mech:'isolation',lv:1,rr:'10–12',load:{back:1,neck:1},setup:'Скамья для пресса: ноги под валики, ляг спиной на подушку. Пальцы у висков, локти в стороны. Повторы — на каждую сторону.',how:['Скрутись вверх и одновременно поверни корпус — плечо тянется к противоположному колену','Поворот идёт от рёбер, а не от локтя','Пауза 1 секунда','Медленно опустись и повтори в другую сторону'],bad:['Тянешь голову руками','Машешь локтем вместо поворота корпуса','Садишься полностью — пресс отдыхает']},
  dbfloor:{n:'Жим гантелей лёжа на полу',g:'chest',img:'mat',t:'w',x2:1,mech:'compound',lv:1,rr:'8–12',load:{shoulder:1,elbow:1},setup:'Сядь на коврик с гантелями на бёдрах и ляг на спину вместе с ними. Ноги согнуты, стопы на полу. Пол ограничивает глубину — щадящий вариант для плеч.',how:['Ладони смотрят друг на друга или вперёд','Опускай гантели, пока локти мягко не коснутся пола','Локти под 45° к корпусу','Короткая пауза и жми вверх','Закончив, опусти гантели к груди и положи на пол сбоку'],bad:['Бросаешь локти на пол — удар по суставу','Локти разведены под 90°','Отрываешь таз от пола']},
  pushup:{n:'Отжимания от пола',g:'chest',img:'mat',t:'r',mech:'compound',lv:1,rr:'8–15',load:{shoulder:1,elbow:1,wrist:1},setup:'На коврике, ладони чуть шире плеч, пальцы вперёд. Тяжело — упрись руками в сиденье горизонтальной скамьи или отжимайся с колен.',how:['Тело — прямая линия от головы до пяток, пресс и ягодицы напряжены','Опускайся, пока грудь почти не коснётся пола','Локти под 45° к корпусу','Выжимай себя вверх, не теряя прямой линии'],bad:['Провисает поясница','Локти разведены в стороны под 90°','Голова тянется к полу раньше груди']},
  birddog:{n:'Птица-собака',g:'core',cr:'stab',img:'mat',t:'r',mech:'isolation',lv:1,rr:'8–10',load:{knee:1,wrist:1},setup:'На коврике на четвереньках: ладони под плечами, колени под тазом. Повторы — на каждую сторону.',how:['Напряги пресс, спина ровная, как столик','Медленно вытяни вперёд руку и назад противоположную ногу до линии корпуса','Задержись на 2 секунды, таз не перекашивается','Верни и повтори другой парой'],bad:['Прогибаешь поясницу, поднимая ногу слишком высоко','Таз разворачивается в сторону','Спешишь — делай медленно']},
  sideabd:{n:'Отведение ноги лёжа на боку',g:'gmed',img:'mat',t:'r',mech:'isolation',lv:1,rr:'15–20',load:{hip:1},setup:'Ляг на бок на коврик, нижняя нога согнута для устойчивости, верхняя прямая. Повторы — на каждую ногу.',how:['Носок верхней ноги смотрит вперёд, не вверх','Поднимай прямую ногу вверх и чуть назад, до 30–40°','Задержись на 1 секунду','Медленно опусти, не касаясь второй ноги'],bad:['Разворачиваешь носок вверх — работает передняя часть бедра','Заваливаешь таз назад','Машешь ногой по инерции']},
  donkey_kick:{n:'Махи ногой назад на четвереньках',g:'glutes',img:'mat',t:'r',mech:'isolation',lv:1,rr:'12–15',load:{knee:1,back:1,wrist:1,hip:1},setup:'На коврике на четвереньках: ладони под плечами, колени под тазом. Колени болят — сложи коврик вдвое. Повторы — на каждую ногу.',how:['Напряги пресс, спина ровная','Не меняя угла в колене (90°), поднимай ногу пяткой к потолку','Остановись, когда бедро на линии корпуса, сожми ягодицу на 1 секунду','Медленно опусти колено, не касаясь пола'],bad:['Нога выше корпуса — поясница прогибается','Таз заваливается на сторону','Рывки с размаху вместо медленного подъёма']},
  fire_hydrant:{n:'Отведение бедра на четвереньках',g:'gmed',img:'mat',t:'r',mech:'isolation',lv:1,rr:'12–15',load:{knee:1,wrist:1,hip:1},setup:'На коврике на четвереньках: ладони под плечами, колени под тазом. Колени болят — сложи коврик вдвое. Повторы — на каждую ногу.',how:['Напряги пресс, вес — на руках и опорном колене','Не меняя угла в колене, отводи бедро в сторону','Поднимай, пока таз не начал крениться, пауза 1 секунда','Медленно опусти'],bad:['Корпус заваливается на опорную сторону','Гонишься за высотой ценой перекоса таза','Округляешь или прогибаешь спину']},
  clamshell:{n:'Ракушка лёжа на боку',g:'gmed',img:'mat',t:'r',mech:'isolation',lv:1,rr:'15–20',load:{hip:1},setup:'Ляг на бок на коврике, голову положи на вытянутую руку. Бёдра согни примерно на 45°, колени — под 90°, пятки на одной линии с ягодицами. Повторы — на каждую сторону.',how:['Пятки прижаты друг к другу','Раскрой верхнее колено вверх, как створку ракушки','Таз не откатывается назад, пауза 1 секунда','Медленно закрой колено'],bad:['Корпус откатывается назад вместе с коленом','Пятки расходятся','Рывки вместо медленного движения']},
  side_leg_raise:{n:'Подъём ноги лёжа на боку',g:'gmed',img:'mat',t:'r',mech:'isolation',lv:1,rr:'12–15',load:{hip:1},setup:'Ляг на бок на коврике, нижнюю ногу согни для устойчивости. Верхняя нога прямая, на одной линии с корпусом или чуть позади. Повторы — на каждую сторону.',how:['Носок верхней ноги смотрит вперёд, не в потолок','Подними прямую ногу на 30–40°, ведя пяткой','Пауза 1 секунда наверху','Медленно опусти, не касаясь нижней ноги'],bad:['Носок разворачивается к потолку — работает уже передняя часть бедра','Нога уходит вперёд от линии корпуса','Махи на инерции']},
  knee_pushup:{n:'Отжимания с колен',g:'chest',img:'mat',t:'r',mech:'compound',lv:1,rr:'8–12',load:{knee:1,shoulder:1,elbow:1,wrist:1},setup:'На коврике: ладони чуть шире плеч, опора на колени, стопы можно скрестить. Колени болят — сложи коврик вдвое или отжимайся от скамьи.',how:['Тело от колен до головы — прямая линия, пресс напряжён','Опускайся грудью к полу, локти под 45° к корпусу','Остановись в паре сантиметров от пола','Выжми себя вверх, сохраняя прямую линию'],bad:['Таз задран вверх или провисает','Локти разведены в стороны под 90°','Тянешься к полу головой, а не грудью']},
  close_pushup:{n:'Отжимания узким хватом',g:'triceps',img:'mat',t:'r',mech:'compound',lv:2,rr:'6–12',load:{shoulder:1,elbow:1,wrist:1},setup:'На коврике: ладони строго под плечами, пальцы смотрят вперёд, опора на носки. Тяжело — делай так же с колен.',how:['Тело — прямая линия, пресс напряжён','Опускайся, локти скользят назад вдоль боков','Грудь почти касается пола','Выжми себя вверх, разгибая руки'],bad:['Локти разъезжаются в стороны','Провисает поясница','Ладони ромбом под грудью — лишняя нагрузка на запястья и локти']},
  superman_alt:{n:'Супермен попеременно',g:'core',cr:'stab',img:'mat',t:'r',mech:'isolation',lv:1,rr:'8–10',load:{back:1,shoulder:1,neck:1},setup:'Ляг на живот на коврике, руки вытяни вперёд. Лоб — на коврике или на сложенном полотенце. Повторы — на каждую сторону.',how:['Слегка напряги пресс и ягодицы','Подними противоположные руку и ногу на 5–10 см','Задержись на 2 секунды, взгляд в пол','Медленно опусти и смени сторону'],bad:['Задираешь голову — грузишь шею','Поднимаешь высоко, сильно прогибаясь в пояснице','Рывки вместо плавного подъёма']},
  hollow_hold:{n:'Лодочка на спине',g:'core',cr:'stab',img:'mat',t:'t',mech:'isolation',lv:2,rr:'20–30',load:{back:1,neck:1,hip:1},setup:'Ляг на спину на коврике. Начни с лёгкого варианта: колени согнуты, руки вытянуты вдоль тела к стопам. Стало легко — выпрями ноги, потом вытяни руки за голову.',how:['Прижми поясницу к полу — это главное','Оторви лопатки и ноги от пола, подбородок слегка к груди','Держи позу, дыши ровно','Поясница начала отрываться — согни колени или подними ноги выше'],bad:['Поясница отрывается от пола','Задираешь подбородок и напрягаешь шею','Задерживаешь дыхание']},
  mountain_climber:{n:'Скалолаз',g:'core',cr:'stab',img:'mat',t:'t',mech:'compound',lv:2,rr:'20–30',load:{back:1,shoulder:1,wrist:1,hip:1},setup:'Планка на прямых руках на коврике, ладони под плечами. Начни медленно, ускоряйся, только если таз остаётся на месте.',how:['Тело — прямая линия, пресс напряжён','Подтяни одно колено к груди','Верни ногу и сразу подтяни другое колено','Плечи всё время над ладонями'],bad:['Таз прыгает вверх-вниз','Плечи уезжают назад за ладони','Провисает поясница']},
  bicycle_crunch:{n:'Скручивания «велосипед»',g:'core',cr:'side',img:'mat',t:'r',mech:'isolation',lv:2,rr:'10–12',load:{back:1,neck:1,hip:1},setup:'Ляг на спину на коврике, поясница прижата. Пальцы у висков, локти в стороны, ноги подняты и согнуты под 90°. Повторы — на каждую сторону.',how:['Оторви лопатки от пола','Поверни корпус, подводя плечо к колену противоположной ноги, другую ногу вытяни вперёд','Медленно смени сторону','Поясница всё время прижата к полу'],bad:['Тянешь голову руками за шею','Машешь локтями вместо поворота корпуса','Вытянутая нога слишком низко — поясница прогибается']},
  bike_intervals:{n:'Велосипед — интервалы',g:'cardio',img:'bike',t:'c',mech:'compound',lv:2,rr:'20',load:{knee:2},setup:'Вертикальный велотренажёр. Сиденье ставь высоко: в нижней точке нога почти прямая. Сопротивление переключай на экране по ходу тренировки.',how:['5 минут легко — разминка','30 секунд быстро и с сопротивлением повыше — до тяжёлого дыхания','90 секунд легко — отдых в движении','Повтори 6–8 раз, в конце 3–5 минут спокойно'],bad:['Слишком тяжёлое сопротивление — страдают колени','Колени разваливаются в стороны','Ускорения без разминки']},
  recumbent_bike:{n:'Горизонтальный велотренажёр',g:'cardio',img:'bike',t:'c',mech:'compound',lv:1,rr:'20',load:{knee:1},setup:'Велотренажёр со спинкой. Отодвинь сиденье так, чтобы в дальней точке нога была почти прямая. Спина и таз прижаты к спинке — хороший вариант, когда беспокоит поясница.',how:['Лёгкое или среднее сопротивление, 70–90 оборотов в минуту','Колени идут ровно вперёд','Темп такой, чтобы можно было говорить'],bad:['Сиденье слишком близко — колени сильно сгибаются','Таз ёрзает по сиденью — сиденье слишком далеко','Колени разваливаются в стороны']},
  // --- дополнение: слабые группы и вариации ---
  dblateral_seated:{n:'Махи гантелями в стороны сидя',g:'side',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Спинку скамьи поставь вертикально или на одно деление ниже. Сядь, прижми спину к спинке, стопы на полу, лёгкие гантели висят по бокам. Спинка не даёт раскачиваться — вес бери меньше, чем стоя.',how:['Локти чуть согнуты, плечи опущены','Поднимай руки в стороны до уровня плеч, локоть ведёт движение','Пауза 1 секунда вверху','Опускай медленно, 2–3 секунды, гантели не касаются бёдер'],bad:['Отрываешь спину от спинки и помогаешь корпусом','Плечи поднимаются к ушам','Кисти выше локтей — вес уходит в трапецию']},
  dblateral_lean:{n:'Махи в сторону с наклоном от стойки',g:'side',img:'db',t:'w',x2:1,mech:'isolation',lv:2,rr:'10–12',load:{shoulder:1},setup:'Встань снаружи рамы Смита боком к передней стойке, возьмись за неё ближней рукой и наклони корпус от стойки, чтобы тело стало прямой наклонной линией. Гантель — в дальней руке. Из-за наклона мышца работает с самого низа, поэтому вес легче, чем в обычных махах. Вес и повторы — на каждую руку.',how:['Стопы у основания стойки, рука на стойке прямая, корпус ровный','Поднимай гантель в сторону до уровня плеча, локоть чуть согнут','Пауза 1 секунда','Опускай медленно до бедра. Сделай все повторы и поменяй сторону'],bad:['Раскачиваешь корпус, чтобы закинуть гантель','Плечо поднимается к уху','Сгибаешь локоть сильнее — амплитуда укорачивается']},
  dblateral_incline:{n:'Махи одной рукой лёжа боком на наклонной',g:'side',img:'bench',t:'w',x2:1,mech:'isolation',lv:2,rr:'10–12',load:{shoulder:1},setup:'Спинку скамьи поставь под 45–60°. Ляг на неё боком: бедро на сиденье, бок на спинке, нижней рукой держись за спинку. Гантель — в верхней руке, висит перед телом. Вес заметно меньше, чем стоя. Вес и повторы — на каждую руку.',how:['Плечо опущено, локоть чуть согнут','Поднимай гантель, пока рука не станет перпендикулярна корпусу — на уровень плеча, не выше','Пауза 1 секунда вверху','Опускай медленно, 2–3 секунды, до касания бедра. Потом другая сторона'],bad:['Разворачиваешься на спину вслед за гантелью','Поднимаешь гантель рывком','Плечо тянется к уху']},
  dblateral_hold:{n:'Удержание гантелей в стороны',g:'side',img:'db',t:'t',mech:'isolation',lv:1,rr:'20–30',load:{shoulder:1},setup:'Стоя, стопы на ширине таза, самые лёгкие гантели (2–4 кг). Руки — в стороны на уровне плеч, локти чуть согнуты, ладони смотрят вниз. Тяжело — держи без гантелей.',how:['Подними руки в стороны до уровня плеч и замри','Плечи опущены, шея расслаблена, дыши ровно','Держи заданное время — руки не опускаются ниже плеч','Опусти медленно, отдохни 1 минуту'],bad:['Плечи ползут к ушам','Руки постепенно опускаются — возьми легче','Задерживаешь дыхание']},
  dbscaption:{n:'Махи гантелями вперёд-в стороны',g:'side',img:'db',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Стоя, лёгкие гантели перед бёдрами, большие пальцы смотрят вверх, как при рукопожатии. Руки идут не строго в стороны и не вперёд, а между — примерно на 30° вперёд от линии плеч. Самый мягкий для плеча вариант махов.',how:['Локти чуть согнуты, большие пальцы вверх','Поднимай руки по диагонали вперёд-в стороны до уровня плеч','Пауза 1 секунда','Опускай медленно к бёдрам'],bad:['Руки уходят строго в стороны или строго вперёд','Раскачка корпусом','Поднимаешь выше плеч, плечи тянутся к ушам']},
  dbreardelt_seated:{n:'Разводка на заднюю дельту сидя в наклоне',g:'rear',img:'bench',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{back:1,shoulder:1},setup:'Сядь на край горизонтальной скамьи, стопы вместе или на ширине таза. Наклонись вперёд и положи грудь на бёдра — так поясница отдыхает. Лёгкие гантели (2–6 кг) висят под голенями, ладони друг к другу.',how:['Грудь лежит на бёдрах, взгляд в пол, плечи опущены','Разводи руки в стороны дугой до линии плеч, локти чуть согнуты','Пауза 1 секунда вверху','Опускай медленно, 2 секунды'],bad:['Отрываешь грудь от бёдер и качаешь корпусом','Сгибаешь локти — получается тяга','Тяжёлые гантели и рывки']},
  cable_reardelt_cross:{n:'Обратная разводка на кроссовере',g:'rear',img:'cable',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{shoulder:1},setup:'Кроссовер: оба блока на уровне плеч, D-рукоятки. Возьми их крест-накрест: правый трос — левой рукой, левый — правой. Отойди на шаг назад, руки скрещены перед грудью и почти прямые, трос натянут. Вес лёгкий.',how:['Стой ровно, колени чуть согнуты, плечи опущены','Разводи руки в стороны и чуть назад до линии плеч, локти чуть согнуты','Пауза 1 секунда — лопатки сведены','Медленно верни руки крест-накрест перед грудью'],bad:['Сгибаешь локти — работает уже спина','Отклоняешься корпусом назад','Плечи поднимаются к ушам']},
  dbcalf_both:{n:'Икры стоя с гантелями',g:'calves',img:'db',t:'w',x2:1,mech:'isolation',lv:1,rr:'12–15',load:{ankle:2},setup:'Положи на пол блин рядом со стойкой Смита и встань на его край подушечками обеих стоп, пятки свисают. По гантели в каждую руку. Шатает — возьми одну гантель, а второй рукой держись за стойку.',how:['Ноги прямые, колени не в замке, корпус ровный','Опусти пятки ниже блина до растяжения икр','Поднимись на носки как можно выше','Пауза 1 секунда вверху, вниз медленно, 2–3 секунды'],bad:['Пружинишь без паузы','Сгибаешь колени и помогаешь бёдрами','Стоишь на самом краю блина — стопа соскальзывает']},
  calf_bent_legpress:{n:'Икры на жиме ногами с согнутыми коленями',g:'calves',img:'legpress',t:'w',mech:'isolation',lv:1,rr:'15–20',load:{knee:1,ankle:2},setup:'Спинку сиденья придвинь ближе, чем для жима, чтобы колени были согнуты примерно под 90° и оставались так всё упражнение. Подушечки стоп — на нижнем краю платформы, пятки висят. Вес лёгкий: с согнутым коленом работает глубокая мышца икры, она слабее.',how:['Колени согнуты и неподвижны, таз прижат к сиденью','Опусти пятки вниз до растяжения','Поднимись на носки как можно выше','Пауза 1 секунда, опускай медленно'],bad:['Разгибаешь колени — толкаешь бедром','Пружинишь без паузы','Стопа на самом краешке — ставь плотно']},
  tibialis_raise:{n:'Подъём носков у стойки',g:'calves',img:'smith',t:'r',mech:'isolation',lv:1,rr:'15–20',load:{ankle:1},setup:'Встань снаружи рамы спиной к стойке Смита (или к стене), прислонись к ней лопатками и ягодицами, стопы выдвинь вперёд на 30–40 см, пятки на полу. Работает передняя мышца голени — она разгружает колени и стопы. Стало легко — отодвинь стопы дальше от стойки.',how:['Ноги прямые, вес на пятках','Поднимай носки к голеням как можно выше','Пауза 1 секунда вверху','Медленно опусти, носки не шлёпают об пол'],bad:['Сгибаешь колени и приседаешь','Отрываешь спину от стойки','Делаешь быстро без паузы']},
  side_plank_abd:{n:'Боковая планка с подъёмом ноги',g:'gmed',img:'mat',t:'r',mech:'isolation',lv:2,rr:'8–12',load:{shoulder:1,hip:1},setup:'На коврике на боку, опора на локоть под плечом, ноги прямые одна на другой. Тяжело — опирайся на согнутое нижнее колено. Повторы — на каждую сторону.',how:['Подними таз: тело — прямая линия от головы до стоп','Не опуская таз, подними верхнюю ногу на 30–40°, носок смотрит вперёд','Пауза 1 секунда','Медленно опусти ногу, таз держи. Потом другая сторона'],bad:['Таз провисает при подъёме ноги','Носок разворачивается в потолок — работает передняя часть бедра','Корпус заваливается вперёд или назад']},
  hip_hike:{n:'Подъём таза стоя на блине',g:'gmed',img:'barbell',t:'r',mech:'isolation',lv:1,rr:'12–15',load:{hip:1,ankle:1},setup:'Положи на пол блин 10–20 кг рядом со стойкой Смита, встань на него одной ногой боком к стойке, ближней рукой держись за неё. Свободная нога висит рядом с блином прямая. Работает боковая ягодичная опорной ноги. Повторы — на каждую сторону.',how:['Опорная нога прямая, колено не сгибай','Опусти таз со стороны свободной ноги — стопа опускается ниже блина','Подними таз той же стороной как можно выше — стопа поднимается выше блина','Движение медленное, только тазом, плечи ровные'],bad:['Сгибаешь и разгибаешь опорное колено','Наклоняешь плечи вместо таза','Висишь на стойке — рука только для равновесия']},
  gmed_wall_press:{n:'Давление коленом в стойку',g:'gmed',img:'smith',t:'t',mech:'isolation',lv:1,rr:'20–30',load:{hip:1},setup:'Встань снаружи рамы боком вплотную к стойке Смита на одной ноге. Ближнюю к стойке ногу согни под 90° и прижми колено к стойке. Работает ягодица опорной — дальней от стойки — ноги. Время — на каждую сторону.',how:['Опорная нога чуть согнута, таз ровный, корпус прямой','Дави согнутым коленом в стойку, не двигаясь','Почувствуй напряжение сбоку ягодицы опорной ноги','Держи заданное время, дыши ровно. Потом другая сторона'],bad:['Таз заваливается в сторону стойки','Наклоняешь корпус','Опорное колено заваливается внутрь']},
  dbcurtsy_lunge:{n:'Реверанс-выпады с гантелями',g:'gmed',img:'db',t:'w',x2:1,mech:'compound',lv:2,rr:'8–10',load:{knee:2,back:1,hip:2,ankle:1},setup:'Гантели в опущенных руках, стопы на ширине таза. Начни без веса, потом бери лёгкие гантели. Шаг назад идёт по диагонали — за опорную ногу, как в реверансе. Переднее колено здесь нагружается с поворотом: болят колени — выбери отведение ноги на блоке. Повторы — на каждую ногу.',how:['Шагни одной ногой назад и по диагонали за опорную, встань на носок','Опускайся, пока заднее колено почти не коснётся пола','Переднее колено идёт по линии носка, таз ровный, корпус чуть наклонён вперёд','Вернись в стойку, толкаясь пяткой передней ноги. Все повторы — потом другая нога'],bad:['Переднее колено заваливается внутрь','Слишком длинный диагональный шаг — таз перекашивается','Отталкиваешься задней ногой вместо передней']},
  lat_neutral:{n:'Тяга верхнего блока нейтральным хватом',g:'backv',img:'lat',t:'w',mech:'compound',lv:1,rr:'8–12',load:{shoulder:1,elbow:1},setup:'Тот же тренажёр верхней тяги. Сиденье — чтобы валики плотно прижали бёдра. Возьмись за вертикальные рукояти на рычагах — ладони смотрят друг на друга. Такой хват мягче для плеч и локтей, чем обычный.',how:['Грудь вперёд, плечи опусти вниз от ушей','Тяни локти вниз и назад к рёбрам','Внизу пауза 1 секунда — лопатки сведены','Вверх медленно, 2 секунды, до почти прямых рук'],bad:['Раскачиваешься корпусом и тянешь поясницей','Плечи поднимаются к ушам вверху','Рывок вниз']},
  pullup_bench_assisted:{n:'Подтягивания с опорой на скамью',g:'backv',img:'cable',t:'r',mech:'compound',lv:1,rr:'6–10',load:{shoulder:1,elbow:1,wrist:1},setup:'Турник сверху кроссовера. Поставь под него горизонтальную скамью, встань на неё и возьмись хватом сверху чуть шире плеч. Согни ноги так, чтобы руки стали прямыми, а стопы остались на скамье. Легче — дави ногами сильнее; тяжелее — оставь на скамье одну ногу.',how:['Плечи опусти вниз, пресс напряжён','Тянись грудью к перекладине, ногами помогай ровно столько, чтобы дотянуть','Подбородок выше перекладины, пауза 1 секунда','Опускайся медленно, 3 секунды, ногами почти не помогай'],bad:['Выпрыгиваешь ногами вместо тяги руками','Тянешься подбородком и вытягиваешь шею','Падаешь вниз на прямые руки']},
  cable_pullup_neutral:{n:'Подтягивания нейтральным хватом',g:'backv',img:'cable',t:'r',mech:'compound',lv:2,rr:'4–8',load:{shoulder:2,elbow:1,wrist:1},setup:'Турник сверху кроссовера: возьмись за угловые концы перекладины — ладони смотрят друг на друга или чуть внутрь. Это самый мягкий для плеч и локтей хват. Не достаёшь — встань на скамью. Не получается ни разу — делай «Подтягивания с опорой на скамью».',how:['Из виса опусти плечи вниз','Тяни локти вниз к рёбрам, грудь к перекладине','Подбородок выше перекладины, пауза 1 секунда','Опускайся медленно, 2–3 секунды, до почти прямых рук'],bad:['Раскачка и рывки ногами','Не опускаешься до конца — половина амплитуды','Плечи поднимаются к ушам внизу']},
  cable_pulldown_kneel:{n:'Тяга верхних блоков стоя на коленях',g:'backv',img:'cable',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{knee:1,shoulder:1,elbow:1},setup:'Кроссовер: оба блока в самый верх, D-рукоятки. Положи коврик между стойками, встань на колени лицом к тренажёру в шаге от него и возьми рукояти. Тросы идут сверху-спереди, руки вытянуты вверх буквой V. Вес — на каждую сторону.',how:['Корпус прямой, чуть наклонён назад, грудь вперёд, плечи опущены','Тяни локти вниз и к бокам, рукояти идут к плечам','Внизу сведи лопатки, пауза 1 секунда','Медленно отпусти вверх до прямых рук, не падая корпусом вперёд'],bad:['Отклоняешься назад и тянешь поясницей','Тянешь руками, локти уходят вперёд','Вес поднимает тебя с коленей — возьми легче']},
  dead_hang:{n:'Вис на турнике',g:'backv',img:'cable',t:'t',mech:'isolation',lv:1,rr:'20–40',load:{shoulder:1,elbow:1,wrist:1},setup:'Турник сверху кроссовера, хват сверху чуть шире плеч. Не достаёшь — встань на скамью, возьмись и аккуратно сойди с неё. Укрепляет хват и плечи и готовит к подтягиваниям.',how:['Повисни на прямых руках, плечи чуть опусти от ушей','Тело спокойно, ноги вместе или скрещены','Дыши ровно, держи заданное время','Сходи на скамью или на пол мягко, не спрыгивай'],bad:['Раскачиваешься','Плечи полностью задраны к ушам — слегка опусти их','Спрыгиваешь на пол на прямые ноги']},
  legcurl_ecc:{n:'Сгибание ног: вверх двумя, вниз одной',g:'hams',img:'legcurl',t:'w',mech:'isolation',lv:2,rr:'6–8',load:{knee:1},setup:'Настройка как для обычного сгибания: ось напротив колена, верхний валик плотно прижимает бёдра. Вес — как в обычном сгибании или чуть легче. Сгибай двумя ногами, а разгибай одной — медленно. Повторы — на каждую ногу.',how:['Согни ноги двумя, подтянув пятки под сиденье','Сдвинь одну ногу в сторону и сними её с валика — она остаётся согнутой сбоку','Рабочей ногой медленно разгибай валик, 4–5 секунд, до почти прямой','Верни вторую ногу на валик и согни двумя. Все повторы — потом другая нога'],bad:['Опускаешь быстро — теряется смысл упражнения','Таз приподнимается с сиденья','Болит под коленом — уменьши вес']},
  smith_good_morning:{n:'Наклоны со штангой в Смите',g:'hams',img:'smith',t:'w',mech:'compound',lv:2,rr:'8–10',load:{back:2,shoulder:1,neck:1,hip:1},setup:'Гриф повесь на крюки на уровне верха груди, нижние упоры выставь примерно на высоте пояса — чуть ниже грифа в твоей нижней точке. Начни с пустого грифа. Стопы на ширине таза, чуть впереди грифа. Болит поясница — выбери румынскую тягу.',how:['Положи гриф на верх трапеций, сними с крюков поворотом кистей, напряги пресс','Слегка согни колени и отводи таз назад — корпус наклоняется вперёд с прямой спиной','Опускайся до растяжения задней поверхности бедра — обычно корпус чуть выше параллели с полом','Вернись вверх, толкая таз вперёд и сжимая ягодицы. В конце поверни гриф на крюки'],bad:['Скругляешь поясницу внизу','Приседаешь вместо наклона — сильно сгибаешь колени','Тяжёлый вес — это упражнение на технику, не на рекорды']},
  db_good_morning:{n:'Наклоны с гантелью у груди',g:'hams',img:'db',t:'w',mech:'compound',lv:1,rr:'10–12',load:{back:1,hip:1},setup:'Одну гантель держи вертикально двумя руками у груди, локти вниз. Стопы на ширине таза, носки вперёд. Учебная версия наклона: учит отводить таз назад с прямой спиной перед румынской тягой.',how:['Колени чуть согнуты и не меняют угол, пресс напряжён','Отводи таз назад — корпус наклоняется вперёд, спина прямая','Опускайся до растяжения задней поверхности бедра, корпус примерно на 45°','Вернись вверх, толкая таз вперёд и сжимая ягодицы'],bad:['Круглая спина','Приседаешь вместо наклона','Прогибаешься назад в верхней точке']},
  legcurl_hold:{n:'Удержание на сгибании ног',g:'hams',img:'legcurl',t:'t',mech:'isolation',lv:1,rr:'20–30',load:{knee:1},setup:'Настройка как для обычного сгибания: ось напротив колена, верхний валик прижимает бёдра. Вес — примерно две трети от рабочего в сгибании: держать 20–30 секунд должно быть тяжело, но без дрожи в суставе.',how:['Согни ноги примерно до прямого угла в колене и замри','Таз прижат, держись за рукояти, дыши ровно','Держи заданное время — валик не поднимается','Медленно разогни ноги, отдохни 1–2 минуты'],bad:['Валик ползёт вверх — держи одну точку','Задерживаешь дыхание','Таз отрывается от сиденья']},
  bridge_walkout:{n:'Мост с шагами пятками',g:'hams',img:'mat',t:'r',mech:'compound',lv:1,rr:'6–8',load:{knee:1,back:1,hip:1},setup:'Ляг на спину на коврик, ноги согнуты, стопы на полу близко к ягодицам. Руки вдоль тела ладонями вниз. Подними таз в мост и держи его всё упражнение.',how:['Подними таз до прямой линии плечи — колени','Не опуская таз, маленькими шагами уводи пятки вперёд, пока ноги не станут почти прямыми','Так же шагами верни пятки к ягодицам','Опусти таз — это один повтор. Легче — шаги короче и ноги не до конца прямые'],bad:['Таз опускается во время шагов','Прогиб в пояснице — рёбра опущены','Шаги быстрые и широкие']},
  bike_zone2:{n:'Велосипед — ровный темп',g:'cardio',img:'bike',t:'c',mech:'compound',lv:1,rr:'30',load:{knee:1},setup:'Вертикальный велотренажёр. Сиденье высоко: в нижней точке нога почти прямая. Сопротивление лёгкое или среднее — такое, чтобы 30 минут держать ровный темп и спокойно говорить фразами.',how:['Первые 3 минуты легко — разминка','Выйди на темп, при котором дышишь глубже, но можешь говорить фразами','Держи 80–90 оборотов в минуту, темп не меняй','Последние 3 минуты сбрось сопротивление — заминка'],bad:['Слишком тяжело — не можешь говорить, это уже интервал','Сиденье низко — грузит колени спереди','Пропускаешь заминку']},
  bike_tabata:{n:'Велосипед — спринты 20/10',g:'cardio',img:'bike',t:'c',mech:'compound',lv:2,rr:'12',load:{knee:2},setup:'Вертикальный велотренажёр, сиденье высоко. Самый тяжёлый протокол: только после разминки и не чаще 1–2 раз в неделю. Разминайся на лёгком сопротивлении, перед первым спринтом переключи на рабочее и больше не трогай — за 10 секунд отдыха менять его не успеешь. Болят колени — пропусти.',how:['5 минут легко — разминка, последние 30 секунд чуть быстрее','20 секунд крути максимально быстро с высоким сопротивлением','10 секунд медленно, не останавливаясь','Повтори 8 раз — 4 минуты, затем 3 минуты совсем легко'],bad:['Сопротивление тяжёлое и каденс падает ниже 80 — колени страдают','Встаёшь с седла и раскачиваешься','Делаешь без разминки или на уставшие ноги']},
  recumbent_intervals:{n:'Горизонтальный велотренажёр — интервалы',g:'cardio',img:'bike',t:'c',mech:'compound',lv:1,rr:'20',load:{knee:1},setup:'Велотренажёр со спинкой. Сиденье отодвинь так, чтобы в дальней точке нога была почти прямая, спина прижата к спинке. Мягкий вариант интервалов — для поясницы и для начала.',how:['4 минуты легко — разминка','1 минута быстрее со средним сопротивлением — дыхание заметно учащается, но говорить ещё можно','2 минуты легко','Повтори 5 раз, в конце 3 минуты спокойно'],bad:['Сопротивление слишком тяжёлое — колени ноют','Таз ёрзает по сиденью — сиденье слишком далеко','Ускорения сразу без разминки']},
  bike_pyramid:{n:'Велосипед — пирамида',g:'cardio',img:'bike',t:'c',mech:'compound',lv:2,rr:'26',load:{knee:2},setup:'Вертикальный велотренажёр, сиденье высоко. Рабочие отрезки растут и потом убывают: 1–2–3–2–1 минута, отдых между ними равен работе. Сопротивление переключай на экране.',how:['5 минут легко — разминка','Работа 1 минута быстро, потом столько же легко; затем 2 и 2, 3 и 3, 2 и 2, 1 и 1','На работе дыхание тяжёлое, но каденс не ниже 80 оборотов','После пирамиды 3 минуты совсем легко'],bad:['Слишком тяжёлое сопротивление — каденс и колени страдают','Сокращаешь отдых — следующий отрезок разваливается','Без разминки']},
  dbpress_neutral:{n:'Жим гантелей сидя нейтральным хватом',g:'press',img:'bench',t:'w',x2:1,mech:'compound',lv:1,rr:'8–12',load:{back:1,shoulder:1,elbow:1},setup:'Спинка почти вертикально, на одно деление ниже максимума. Закинь гантели к плечам, ладони смотрят друг на друга, локти направлены вперёд, а не в стороны. Самый мягкий для плеч вариант жима — выбери его, если в плече щёлкает.',how:['Спина и голова прижаты к спинке, пресс напряжён','Жми вверх, гантели идут над плечами и чуть сходятся вверху','Локти не выпрямляй до щелчка','Опускай медленно до уровня подбородка, локти остаются впереди'],bad:['Прогиб в пояснице — таз отрывается','Локти разъезжаются в стороны — это уже обычный жим','Гантели уходят вперёд, а не вверх над плечами']},
  dbpress_standing:{n:'Жим гантелей стоя',g:'press',img:'db',t:'w',x2:1,mech:'compound',lv:2,rr:'8–10',load:{back:2,shoulder:1,elbow:1},setup:'Стоя, стопы на ширине таза, колени чуть согнуты. Закинь гантели к плечам с бёдер. Вес легче, чем в жиме сидя: без спинки корпус держит пресс. Болит поясница — жми сидя.',how:['Пресс и ягодицы напряжены, рёбра опущены','Жми вверх, гантели над плечами, не отклоняясь назад','Вверху локти почти прямые, гантели над макушкой','Опускай медленно до уровня ушей'],bad:['Отклоняешься назад и прогибаешь поясницу','Подпрыгиваешь ногами, помогая жиму','Гантели уходят вперёд перед лицом']},
  cable_oh_press_1arm:{n:'Жим вверх одной рукой на блоке с колена',g:'press',img:'cable',t:'w',x2:1,mech:'compound',lv:1,rr:'10–12',load:{knee:1,shoulder:1,elbow:1},setup:'Кроссовер: блок в самый низ, D-рукоять. Встань спиной к стойке на одно колено на коврике: внизу колено той же стороны, что рабочая рука, передняя нога впереди под 90°. Рукоять подними к плечу, трос идёт за спиной. Вес и повторы — на каждую руку.',how:['Корпус прямой, пресс напряжён, таз подкручен — не прогибайся','Выжми рукоять вверх над плечом, в конце ладонь смотрит вперёд','Не выпрямляй локоть до щелчка','Медленно опусти к плечу. Потом другая рука'],bad:['Наклоняешься в сторону от рабочей руки','Прогиб в пояснице','Рукоять уходит вперёд, а не вверх']},
  pike_pushup:{n:'Отжимания уголком',g:'press',img:'mat',t:'r',mech:'compound',lv:2,rr:'6–10',load:{shoulder:2,elbow:1,wrist:2,neck:1},setup:'На коврике: ладони чуть шире плеч, таз поднят высоко вверх, ноги почти прямые — тело буквой Л. Чем ближе стопы к рукам, тем больше нагрузка на плечи. Тяжело — поставь ладони на край сиденья скамьи, а стопы оставь на полу.',how:['Голова между рук, взгляд на стопы, спина ровная','Сгибай локти и опускай макушку к полу между ладонями','Локти идут назад-в стороны под 45°, не разлетаются','Выжми себя вверх до прямых рук, таз остаётся высоко'],bad:['Опускаешь таз — получаются обычные отжимания','Бьёшься головой об пол — останавливайся в паре сантиметров','Локти разведены строго в стороны']},
};
